     1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
     2	import React from 'react';
     3	import { expect, within } from 'storybook/test';
     4	import { Box } from '@chakra-ui/react';
     5	import { ZimmProductMeta } from '.';
     6	
     7	const meta: Meta<typeof ZimmProductMeta> = {
     8	  title: 'Commerce/ZimmProductMeta',
     9	  component: ZimmProductMeta,
    10	  argTypes: {
    11	    modelInfo: { control: 'text' },
    12	    styleCode: { control: 'text' },
    13	  },
    14	  decorators: [
    15	    // The block sits in the 218px info column; at Storybook's default canvas width the 28px
    16	    // rhythm reads as arbitrary whitespace rather than as the design's spacing.
    17	    (Story: React.ComponentType) => (
    18	      <Box width="218px">
    19	        <Story />
    20	      </Box>
    21	    ),
    22	  ],
    23	};
    24	export default meta;
    25	
    26	type Story = StoryObj<typeof ZimmProductMeta>;
    27	
    28	// One story only. The two collapse branches — style code alone, and neither field — are
    29	// asserted in index.test.tsx instead: they are render-branch decisions, which is the cheaper
    30	// layer per testing.md. What cannot be proven there, and is the whole reason this `play` exists,
    31	// is the resolved spacing.
    32	export const Default: Story = {
    33	  args: {
    34	    modelInfo: 'Model is 5’9.5"/178cm, bust size 32C/10C and wears a size 0',
    35	    styleCode: '8637DS241',
    36	  },
    37	  play: async ({ canvasElement }) => {
    38	    const root = within(canvasElement).getByTestId('product-meta');
    39	
    40	    // 28px, asserted as a computed value for the same reason ZimmProductContent's
    41	    // RhythmWithDescription does it: a change to SPACE_META_ROW, to the recipe, or to the
    42	    // recipe's registration in theme/components/index.ts all surface here rather than only in a
    43	    // visual review. That last one has no other detection anywhere — an unregistered recipe
    44	    // makes useMultiStyleConfig return an empty object, which tsc and eslint both accept.
    45	    //
    46	    // `rowGap`, not `gap`: a real browser expands the shorthand, so reading `gap` off a computed
    47	    // style returns '' here. This is also why the assertion cannot live in the Vitest suite —
    48	    // jsdom does not expand it, and there is no ChakraProvider there to resolve the recipe.
    49	    await expect(getComputedStyle(root).rowGap).toBe('28px');
    50	
    51	    // The same const drives the space above the block, so pin both. Asserting only the gap is
    52	    // how the design's two 28px hops silently drift apart.
    53	    await expect(getComputedStyle(root).paddingTop).toBe('28px');
    54	  },
    55	};

