===== zimmProductMeta/index.tsx =====
     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	import { ZimmProductModelInfo } from 'app/components/ui-kits/atoms/zimmProductModelInfo';
     4	import { ZimmProductStyleCode } from 'app/components/ui-kits/atoms/zimmProductStyleCode';
     5	import { isBlankRichText } from 'app/utils/richText';
     6	
     7	const ZIMM_PRODUCT_META_RECIPE = 'ZimmProductMeta';
     8	
     9	type ZimmProductMetaProps = {
    10	  /**
    11	   * Model copy from the product's `c_modelFit` attribute, rich text as authored in Business
    12	   * Manager. Not populated on most catalogue products today.
    13	   */
    14	  modelInfo?: string;
    15	  /**
    16	   * The master product's style number. Named to match `PdpProductInfo`'s field rather than the
    17	   * atom's `value`, so the page can hand this block the mapper's output directly.
    18	   */
    19	  styleCode?: string;
    20	};
    21	
    22	/**
    23	 * Molecule — the PDP meta block: the model line and the style code, in the order the design
    24	 * places them beneath the accordions at the bottom of the info column.
    25	 *
    26	 * Both children already collapse on their own, so this exists for the spacing: the recipe owns
    27	 * the 28px above the block and the 28px between its two rows.
    28	 */
    29	export const ZimmProductMeta = ({ modelInfo, styleCode }: ZimmProductMetaProps) => {
    30	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_META_RECIPE, {});
    31	
    32	  // LOAD-BEARING, not a redundant echo of the children's own guards. Every other collapse in
    33	  // ui-kits/ happens in an atom and the parent spaces whatever rendered with `gap` alone —
    34	  // zimmProductContent.css.ts documents exactly that, and it works because a `gap` applies only
    35	  // between rendered items, so an all-null column measures zero. This recipe also carries a
    36	  // `paddingTop`, and padding is unconditional: without this guard, a product with neither a
    37	  // style code nor model copy would still push 28px of empty space below the accordions.
    38	  //
    39	  // The predicate deliberately repeats zimmProductModelInfo/index.tsx:19's
    40	  // `isBlankRichText(modelInfo)`. DRY holds at the logic level — `isBlankRichText`
    41	  // (app/utils/richText.tsx) is the one shared implementation — so what repeats is the
    42	  // *decision* about what counts as absent. If the atom's guard ever changes, this must follow.
    43	  if (isBlankRichText(modelInfo) && !styleCode) return null;
    44	
    45	  return (
    46	    <chakra.div __css={styles.root} data-testid="product-meta">
    47	      <ZimmProductModelInfo modelInfo={modelInfo} />
    48	      <ZimmProductStyleCode value={styleCode} />
    49	    </chakra.div>
    50	  );
    51	};

===== zimmProductMeta/index.test.tsx =====
     1	/**
     2	 * Scoped to this molecule's own contract per testing.md: which of its two rows render, and
     3	 * whether the block itself renders at all.
     4	 *
     5	 * `app/utils/richText` is mocked, the same way the two child atoms' own suites mock it — its
     6	 * behaviour is exhaustively proven in app/utils/richText.test.tsx. The atoms themselves are left
     7	 * real, because half of what is asserted here is composition: which atom occupies which slot,
     8	 * and that each still collapses independently inside this wrapper.
     9	 *
    10	 * The all-absent case is the reason this file exists. This molecule's recipe carries a
    11	 * `paddingTop`, and padding is unconditional — unlike the `gap` that every other group in
    12	 * ui-kits/ relies on, it does not collapse when the children render nothing. Without the guard
    13	 * in index.tsx, a product with neither model copy nor a style code would push 28px of empty
    14	 * space below the accordions.
    15	 */
    16	import React from 'react';
    17	import { describe, test, expect, vi, beforeEach } from 'vitest';
    18	import { render, screen } from '@testing-library/react';
    19	
    20	const parseRichText = vi.fn();
    21	const isBlankRichText = vi.fn();
    22	vi.mock('app/utils/richText', () => ({
    23	  parseRichText: (html?: string | null) => parseRichText(html),
    24	  isBlankRichText: (html?: string | null) => isBlankRichText(html),
    25	}));
    26	
    27	import { ZimmProductMeta } from './index';
    28	
    29	const MODEL_COPY = 'Model is 178cm and wears a size 0';
    30	
    31	beforeEach(() => {
    32	  vi.clearAllMocks();
    33	});
    34	
    35	describe('ZimmProductMeta', () => {
    36	  test('renders both rows when the product has model copy and a style code', () => {
    37	    isBlankRichText.mockReturnValue(false);
    38	    parseRichText.mockReturnValue([MODEL_COPY]);
    39	
    40	    render(<ZimmProductMeta modelInfo={MODEL_COPY} styleCode="8637DS241" />);
    41	
    42	    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
    43	    expect(screen.getByTestId('product-model-info')).toHaveTextContent(MODEL_COPY);
    44	    expect(screen.getByTestId('product-style-code')).toBeInTheDocument();
    45	  });
    46	
    47	  test('renders the model line alone when there is no style code', () => {
    48	    isBlankRichText.mockReturnValue(false);
    49	    parseRichText.mockReturnValue([MODEL_COPY]);
    50	
    51	    render(<ZimmProductMeta modelInfo={MODEL_COPY} />);
    52	
    53	    // The block must survive one absent row. A guard written with `||` instead of `&&` would
    54	    // drop the whole thing here, taking real model copy off the page.
    55	    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
    56	    expect(screen.getByTestId('product-model-info')).toBeInTheDocument();
    57	    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
    58	  });
    59	
    60	  test('renders the style code alone when there is no model copy', () => {
    61	    isBlankRichText.mockReturnValue(true);
    62	    parseRichText.mockReturnValue([]);
    63	
    64	    render(<ZimmProductMeta styleCode="8637DS241" />);
    65	
    66	    // The common production shape: `c_modelFit` is unpopulated on most catalogue products, so
    67	    // this is the branch most shoppers see rather than an edge case.
    68	    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
    69	    expect(screen.queryByTestId('product-model-info')).not.toBeInTheDocument();
    70	    expect(screen.getByTestId('product-style-code')).toBeInTheDocument();
    71	  });
    72	
    73	  test.each([undefined, ''])('renders nothing at all when model copy is blank and styleCode is %s', (styleCode) => {
    74	    isBlankRichText.mockReturnValue(true);
    75	    parseRichText.mockReturnValue([]);
    76	
    77	    render(<ZimmProductMeta modelInfo="<p></p>" styleCode={styleCode} />);
    78	
    79	    // Not "renders an empty div" — nothing. The wrapper's own `paddingTop` would otherwise be
    80	    // 28px of visible space with no content in it.
    81	    expect(screen.queryByTestId('product-meta')).not.toBeInTheDocument();
    82	    expect(screen.queryByTestId('product-model-info')).not.toBeInTheDocument();
    83	    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
    84	  });
    85	});

===== zimmProductMeta/zimmProductMeta.css.ts =====
     1	/**
     2	 * Recipe for the PDP meta block — the model line and the style code, which the design places
     3	 * at the bottom of the info column below the accordions.
     4	 *
     5	 * Multipart with a single `root` part rather than a bare `baseStyle`: `ui-kits/recipeParts.test.ts`
     6	 * reconciles a declared `parts` array against what the sibling component actually reads off
     7	 * `useMultiStyleConfig`, and a recipe with no `parts` key is skipped by that walk entirely.
     8	 * Declaring the one part buys the reconciliation for the two-node shape this block will grow
     9	 * into when the designer settles the label/value question raised in `zimmProductStyleCode.css.ts`.
    10	 */
    11	
    12	/**
    13	 * DS: 28px between the drawers and the model line, and again between the model line and the
    14	 * style code — identical on both breakpoints (pdp/product-content, desktop and mobile Default).
    15	 * Figma: pdp/product-content, Desktop Default 40000307:14062 / Mobile Default 40000343:9727.
    16	 * No named scale step exists for 28px: `spacing.ts` brackets it at `xl` (24px) and `2xl` (32px),
    17	 * and while `--zimm-scale-700` does hold 28px, `theme/index.ts` (lines 47-49) records that the
    18	 * numeric aliases exist only for the `.zimm-*` global classes, not as a component-facing
    19	 * surface. Pending a named 28px step from the UI designer — do not swap for `xl` or `2xl`,
    20	 * both visibly wrong.
    21	 */
    22	const SPACE_META_ROW = '1.75rem'; // 28px at the default 16px root
    23	
    24	export const ZimmProductMeta = {
    25	  parts: ['root'],
    26	  baseStyle: {
    27	    // One const drives both hops because the design measures both at 28px. Written as a `gap`
    28	    // plus a `paddingTop` on the same container — the pattern `footer.css.ts` (lines 41-42)
    29	    // already uses with its own SPACE_SECTION — so the two cannot drift apart.
    30	    root: {
    31	      display: 'flex',
    32	      flexDirection: 'column',
    33	      alignItems: 'flex-start',
    34	      gap: SPACE_META_ROW, // model line -> style code
    35	      paddingTop: SPACE_META_ROW, // drawers -> model line
    36	    },
    37	  },
    38	};

