    23	 * requests entries with no `locale` parameter, so a `uiCopy` lookup would serve the space
    24	 * default to all eight storefronts regardless of site. zimmSubscribeModal/index.tsx hardcodes
    25	 * its copy the same way.
    26	 */
    27	export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
