/**
 * Scoped to this molecule's own contract per testing.md: which of its two rows render, in which
 * order, and whether the block itself renders at all.
 *
 * `app/utils/richText` is mocked, the same way the two child atoms' own suites mock it — its
 * behaviour is exhaustively proven in app/utils/richText.test.tsx. The mocks are
 * `mockImplementation`, not `mockReturnValue`: a fixed return ignores its argument, so a
 * molecule that dropped `modelInfo` on the way to the atom, or handed the guard `styleCode`
 * instead of `modelInfo`, would still produce exactly the render the test expected. Keying each
 * mock off its input is what makes those two prop-to-state mistakes fail here.
 *
 * The atoms are left real because composition is part of the contract: `index.tsx` fixes the
 * model line above the style code, asserted below by position rather than by presence, and each
 * atom must still collapse independently inside this wrapper.
 *
 * The all-absent case is the reason this file exists. This molecule's recipe carries a
 * `paddingTop`, and padding is unconditional — unlike the `gap` that every other group in
 * ui-kits/ relies on, it does not collapse when the children render nothing. Without the guard
 * in index.tsx, a product with neither model copy nor a style code would push 28px of empty
 * space below the accordions.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';

const parseRichText = vi.fn();
const isBlankRichText = vi.fn();
vi.mock('app/utils/richText', () => ({
  parseRichText: (html?: string | null) => parseRichText(html),
  isBlankRichText: (html?: string | null) => isBlankRichText(html),
}));

import { ZimmProductMeta } from './index';

const MODEL_COPY = 'Model is 178cm and wears a size 0';
const STYLE_CODE = '8637DS241';

beforeEach(() => {
  vi.clearAllMocks();
  // Input-sensitive by design — see the file docstring. MODEL_COPY is the one value these tests
  // treat as real rich text; everything else, including the `<p></p>` that Business Manager
  // saves for an empty field, is blank.
  isBlankRichText.mockImplementation((html?: string | null) => html !== MODEL_COPY);
  parseRichText.mockImplementation((html?: string | null) => (html === MODEL_COPY ? [MODEL_COPY] : []));
});

describe('ZimmProductMeta', () => {
  test('renders both rows, model line first, when the product has model copy and a style code', () => {
    render(<ZimmProductMeta modelInfo={MODEL_COPY} styleCode={STYLE_CODE} />);

    const root = screen.getByTestId('product-meta');
    expect(root).toBeInTheDocument();
    expect(screen.getByTestId('product-model-info')).toHaveTextContent(MODEL_COPY);
    expect(screen.getByTestId('product-style-code')).toBeInTheDocument();

    // By position, not just presence. The recipe spaces these with one symmetrical `gap`, so
    // swapping the two children in index.tsx changes nothing measurable — the block still has
    // two rows 28px apart, with the style code above the model line. Only order catches it.
    expect(root.children[0]).toBe(screen.getByTestId('product-model-info'));
    expect(root.children[1]).toBe(screen.getByTestId('product-style-code'));
  });

  test('renders the model line alone when there is no style code', () => {
    render(<ZimmProductMeta modelInfo={MODEL_COPY} />);

    // The block must survive one absent row. A guard written with `||` instead of `&&` would
    // drop the whole thing here, taking real model copy off the page — and so would a guard
    // that tested `styleCode` where it should test `modelInfo`.
    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
    expect(screen.getByTestId('product-model-info')).toBeInTheDocument();
    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
  });

  test('renders the style code alone when there is no model copy', () => {
    render(<ZimmProductMeta styleCode={STYLE_CODE} />);

