type Story = StoryObj<typeof ZimmProductMeta>;

// One story only. The two collapse branches — style code alone, and neither field — are
// asserted in index.test.tsx instead: they are render-branch decisions, which is the cheaper
// layer per testing.md. What that suite cannot reach, and is the whole reason this `play`
// exists, is the spacing as a browser actually computes it — see the note on the assertion.
export const Default: Story = {
  args: {
    modelInfo: 'Model is 5’9.5"/178cm, bust size 32C/10C and wears a size 0',
    styleCode: '8637DS241',
  },
  play: async ({ canvasElement }) => {
    const root = within(canvasElement).getByTestId('product-meta');

    // 28px, asserted as a computed value for the same reason ZimmProductContent's
    // RhythmWithDescription does it: a change to SPACE_META_ROW or to the recipe surfaces here
    // rather than only in a visual review.
    //
    // No longer the only detection of an unregistered recipe: index.test.tsx pins the same
    // declaration under a ChakraProvider and theme/index.test.tsx pins the registration itself.
    // What only a real browser can prove is the *used* value — jsdom hands the declared token
    // straight back ('1.75rem') and never resolves rem against the root font size, so 28px on a
    // shopper's screen is asserted here and nowhere else.
    //
    // `rowGap`, not `gap`: the longhand names the one axis this column spaces on. Both resolve
    // in a browser — Chromium returns '28px' for gap, rowGap and columnGap alike, and an element
    // with no gap at all returns 'normal' — but only the longhand is browser-only, because jsdom
    // does not expand the shorthand and reads rowGap back as 'normal' there.
    await expect(getComputedStyle(root).rowGap).toBe('28px');

    // The same const drives the space above the block, so pin both. Asserting only the gap is
    // how the design's two 28px hops silently drift apart.
    await expect(getComputedStyle(root).paddingTop).toBe('28px');
  },
};

